/**
 * Cedar & Stone — OpenAI image-generation spend gate.
 *
 * Per `docs/studio-production-lane-doctrine-v1-locked.md`, the visual asset is
 * generated by the provider, not hand-built here. This test builds the exact
 * request that would be sent, proves it carries none of the customer's facts, and
 * does the resolution arithmetic that decides whether the provider can serve the
 * boxes the composition wants to fill at the customer's requested print size.
 *
 * It spends nothing. No network call is made and none is possible: the request is
 * an object, and the gate report it writes records `authorized: false`.
 */

import { mkdirSync, writeFileSync } from "fs";
import path from "path";
import { describe, expect, it } from "vitest";

import { studioAutonomousProductionLoopV1 } from "@/config/studio-autonomous-production-loop-v1";
import { studioProductionLaneDoctrineV1 } from "@/config/studio-production-lane-doctrine-v1";
import { studioStaticDesignCompositionV1 as cfg } from "@/config/studio-static-design-composition-v1";

import { modularThirdsImageBoxes } from "./compose-flyer-modular-thirds";
import {
  bestSizeForBox,
  buildCustomerDirectionImageRequest,
  buildSpendGateReport,
  type CustomerVisualDirection,
  type GeneratedAssetSlot,
} from "./customer-direction-image-request";

const REPO = path.resolve(__dirname, "../../..");
const PKG = "studio-operating-static-design-composition-rebuild-1";
const GATE_DIR = path.join(REPO, "docs", "launch", PKG, "artifacts", "cedar-stone");

/** The fixed customer brief. Unchanged from the customer-direction proof. */
const BRIEF = {
  customer: "Cedar & Stone Home Organizing",
  styleDirection:
    "bright, elevated, warm, calm, editorial, polished; not childish, not cluttered, not overly corporate",
  visualDirection:
    "airy sunlit home interior with natural textures, soft neutral palette with one muted green accent; image should feel premium and realistic, not generic stock-photo-like",
  layoutDirection:
    "strong visual hierarchy, generous breathing room, image and type should feel intentionally integrated; avoid one giant opaque text box covering the art",
  audience:
    "busy homeowners who want their homes to feel calmer and more organized",
  headline: "Make Space for What Matters",
  body: "Refresh your home this spring with thoughtful, practical organizing support designed around the way you actually live.",
  offerName: "Spring Reset Special",
  offerDetail: "3-hour home organizing session — $225",
  price: "$225",
  cta: "Book Your Consultation",
  web: "cedarandstone.com",
  phone: "(404) 555-0187",
  footer: "Serving Metro Atlanta",
} as const;

/** Everything the renderer owns. None of it may reach the provider. */
const FACTS_OUTSIDE_IMAGE_LAYER = [
  { factId: "businessName", value: BRIEF.customer },
  { factId: "headline", value: BRIEF.headline },
  { factId: "body", value: BRIEF.body },
  { factId: "offerName", value: BRIEF.offerName },
  { factId: "offerDetail", value: BRIEF.offerDetail },
  { factId: "priceDisplay", value: BRIEF.price },
  { factId: "cta", value: BRIEF.cta },
  { factId: "phone", value: BRIEF.phone },
  { factId: "webDisplay", value: BRIEF.web },
  { factId: "disclaimer", value: BRIEF.footer },
] as const;

const DIRECTION: CustomerVisualDirection = {
  visualDirection: BRIEF.visualDirection,
  styleDirection: BRIEF.styleDirection,
  layoutDirection: BRIEF.layoutDirection,
  audience: BRIEF.audience,
  lockedFacts: FACTS_OUTSIDE_IMAGE_LAYER.map((fact) => fact.value),
};

/**
 * The sheet the customer asked for: 8.5in x 11in at 300 DPI. 1536 logical units
 * materialise to 3300px (11in) and 1187 to 2550px (8.5in).
 */
const LOGICAL = { widthPx: 1187, heightPx: 1536 };
const PRINT_SCALE =
  (cfg.print.referenceSheetHeightIn * cfg.print.dpi) / LOGICAL.heightPx;

const BOXES = modularThirdsImageBoxes(LOGICAL.widthPx);

const SLOTS: readonly GeneratedAssetSlot[] = [
  {
    elementId: BOXES.hero.elementId,
    role: "hero",
    subject:
      "an airy sunlit living space in a well-kept home: low morning light across a wooden floor, a linen-covered seat, a shelf of neatly arranged books and folded textiles, a potted plant, plaster walls",
    logicalBox: { width: BOXES.hero.width, height: BOXES.hero.height },
    printScale: PRINT_SCALE,
    dpi: cfg.print.dpi,
    focalControlled: true,
  },
  {
    elementId: BOXES.textureInset.elementId,
    role: "texture_inset",
    subject:
      "a close detail of natural material: woven linen and pale oak grain in low side light, with a single muted green thread running through the weave",
    logicalBox: {
      width: BOXES.textureInset.width,
      height: BOXES.textureInset.height,
    },
    printScale: PRINT_SCALE,
    dpi: cfg.print.dpi,
    focalControlled: true,
  },
];

const REQUESTS = SLOTS.map((slot) =>
  buildCustomerDirectionImageRequest({ direction: DIRECTION, slot }),
);

const REPORT = buildSpendGateReport({
  requests: REQUESTS,
  factsOutsideImageLayer: FACTS_OUTSIDE_IMAGE_LAYER,
  attemptBudget: studioAutonomousProductionLoopV1.maxInternalProductionAttempts,
});

describe("Cedar & Stone image-generation spend gate", () => {
  it("spends nothing and is not authorized", () => {
    expect(REPORT.authorized).toBe(false);
    expect(REQUESTS).toHaveLength(2);
    for (const request of REQUESTS) {
      expect(request.provider).toBe("openai");
      expect(request.model).toBe("gpt-image-1");
      expect(request.n).toBe(1);
    }
  });

  it("carries no customer fact into any prompt", () => {
    expect(REPORT.allPromptsFactLeakFree).toBe(true);
    for (const request of REQUESTS) {
      const prompt = request.prompt.toLowerCase();
      for (const fact of FACTS_OUTSIDE_IMAGE_LAYER) {
        expect(prompt, `${fact.factId} leaked`).not.toContain(fact.value.toLowerCase());
      }
      // Fact-shaped tokens, independent of this brief's exact strings.
      expect(request.prompt).not.toMatch(/\$\d|\(\d{3}\)|\.com|https?:/i);
      // The provider is told not to draw words at all.
      expect(request.prompt).toMatch(/no text, letters, numbers, words/i);
    }
  });

  it("keeps the customer's own visual and style direction in the request", () => {
    const hero = REQUESTS[0]!;
    expect(hero.prompt).toContain(BRIEF.visualDirection);
    expect(hero.prompt).toContain(BRIEF.styleDirection);
    // The direction the customer gave against flat, generic art.
    expect(hero.prompt).toMatch(/not an illustration, not a render, not a flat vector scene/i);
  });

  it("asks for the shape each box actually needs", () => {
    // The hero band is wide; the inset is square.
    expect(bestSizeForBox({ width: 1187, height: 596 })).toBe("1536x1024");
    expect(REQUESTS[0]!.size).toBe("1536x1024");
    expect(REQUESTS[1]!.size).toBe("1024x1024");
  });

  it("reports the full-width hero band as a resolution shortfall rather than upscaling it", () => {
    const hero = REQUESTS[0]!.resolution;
    // 8.5in x 4.27in of sheet, at 300 DPI.
    expect(hero.boxPrintPx).toEqual({ width: 2550, height: 1280 });
    expect(hero.boxInches.width).toBeCloseTo(8.5, 2);
    // gpt-image-1's widest output is 1536px. That is 60% of what the box needs.
    expect(hero.sourceScale).toBeLessThan(1);
    expect(hero.meetsCropHeadroom).toBe(false);
    expect(hero.effectivePpi).toBeLessThan(cfg.print.dpi);
    // And a source narrower than its box has no horizontal focal latitude at all.
    expect(hero.focalLatitude.horizontal).toBe(false);
    expect(REPORT.resolutionShortfalls.map((entry) => entry.elementId)).toEqual([
      "generated-hero",
    ]);
  });

  it("confirms the texture inset is servable at true print resolution", () => {
    const inset = REQUESTS[1]!.resolution;
    expect(inset.meetsCropHeadroom).toBe(true);
    expect(inset.sourceScale).toBeGreaterThanOrEqual(cfg.cropHeadroom.minimumSourceScale);
    expect(inset.effectivePpi).toBeGreaterThan(cfg.print.dpi);
  });

  it("prices the run from the transcribed rate card, flagged as unreconciled", () => {
    for (const request of REQUESTS) {
      expect(request.cost.imageOutputTokens).toBeGreaterThan(0);
      // Generated pixels dominate; prompt text is rounding error.
      expect(request.cost.imageOutputUsd).toBeGreaterThan(request.cost.textInputUsd * 50);
      expect(request.cost.ratesVerifiedAgainstLiveBilling).toBe(false);
    }
    expect(REPORT.totalEstimatedUsd).toBeGreaterThan(0);
    expect(REPORT.totalEstimatedUsd).toBeLessThan(1);
    expect(REPORT.attemptBudget).toBe(3);
    expect(REPORT.worstCaseUsd).toBeCloseTo(REPORT.totalEstimatedUsd * 3, 3);
  });

  it("names the lane rule this proof is now operating under", () => {
    const lane = studioProductionLaneDoctrineV1.lanes.find(
      (candidate) => candidate.id === "static_creative",
    )!;
    expect(lane.certified).toBe(false);
    expect(lane.forbidden).toContain(
      "hand-authored vector scenes standing in for photographic art",
    );
    expect(lane.forbidden).toContain(
      "tiling several generations into one subject to reach print size",
    );
    expect(studioProductionLaneDoctrineV1.certificationRule.maxSeriousAttempts).toBe(3);
  });

  it("writes the gate report for the Owner", () => {
    mkdirSync(GATE_DIR, { recursive: true });
    writeFileSync(
      path.join(GATE_DIR, "image-generation-spend-gate.json"),
      `${JSON.stringify(REPORT, null, 2)}\n`,
      "utf8",
    );
    expect(REPORT.requests[0]!.prompt.length).toBeGreaterThan(200);
  });
});
